<script setup lang="ts">definePageMeta({layout:'admin',middleware:'admin'});const {data,refresh}=await useFetch('/api/admin/media');const csrf=useCsrf();async function upload(e:Event){const file=(e.target as HTMLInputElement).files?.[0];if(!file)return;const body=new FormData();body.append('file',file);await $fetch('/api/admin/media',{method:'POST',headers:csrf.value,body});await refresh()}</script><template><div><div class="flex justify-between"><h1 class="text-3xl font-semibold">媒体库</h1><label class="cursor-pointer rounded-full px-5 py-2 text-white" style="background:var(--accent)">上传<input type="file" class="hidden" @change="upload"></label></div><div class="mt-8 grid grid-cols-2 md:grid-cols-4 gap-4"><figure v-for="m in data||[]" :key="m.id" class="rounded-xl border overflow-hidden" style="border-color:var(--border)"><img v-if="m.type==='IMAGE'" :src="m.url" :alt="m.alt||m.filename" class="aspect-square w-full object-cover"><div v-else class="aspect-square grid place-items-center text-4xl">◫</div><figcaption class="truncate p-3 text-sm">{{m.filename}}</figcaption></figure></div></div></template>
